module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    wire [31:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Golden model function for Galois LFSR (32, 22, 2, 1)
    // Taps at 32, 22, 2, 1 correspond to indices 31, 21, 1, 0 in 0-indexed [31:0]
    function [31:0] next_lfsr;
        input [31:0] current;
        reg fb;
        begin
            fb = current[0];
            next_lfsr = {fb, current[31:1]} ^ ({32{fb}} & 32'h80400003);
        end
    endfunction

    reg [31:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        expected_q = 32'h00000001;

        // Apply reset for a few cycles
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        // Release reset
        reset = 0;

        // Check against golden model for 20 clock cycles
        for (i = 0; i < 20; i = i + 1) begin
            expected_q = next_lfsr(expected_q);
            @(posedge clk);
            #1; // small delay to sample after clock edge

            if (q !== expected_q) begin
                errors = errors + 1;
            end
        end

        // Test asynchronous/synchronous reset behavior mid-stream
        reset = 1;
        expected_q = 32'h00000001;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;
        expected_q = next_lfsr(expected_q);
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        // Final status report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
